verified_declarations.signature:
∀ {n : ℕ} (H : BfgsVerification.Mat n) (g y : BfgsVerification.Vec n) (α : ℝ),
  α ≠ 0 →
    BfgsVerification.metricEnergy H g ≠ 0 →
      -BfgsVerification.dot y (Matrix.mulVec H g) / BfgsVerification.metricEnergy H g ≠ 0 →
        let q := BfgsVerification.metricEnergy H g;
        let β := -BfgsVerification.dot y (Matrix.mulVec H g) / q;
        let v := Matrix.mulVec H g;
        BfgsVerification.inverseBFGS H (BfgsVerification.bfgsStep H g α) y =
          (1 + (β * q)⁻¹ • BfgsVerification.outer v y) * H * (1 + (β * q)⁻¹ • BfgsVerification.outer y v) +
            (α / (β * q)) • BfgsVerification.outer v v
